INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES
(1, 1, 'Một người bình luận WordPress', 'wapuu@wordpress.example', 'https://vi.wordpress.org/', '', '2026-09-09 01:54:08', '2026-09-09 01:54:08', 'Xin chào, đây là một bình luận.\nĐể bắt đầu kiểm duyệt, chỉnh sửa và xóa nhận xét, vui lòng truy cập màn hình Nhận xét trong trang quản trị.\nHình đại diện của người bình luận đến từ <a href=\"https://gravatar.com/\">Gravatar</a>.', 0, 'post-trashed', '', 'comment', 0, 0),
(2, 17, 'admin', 'tranthitrucanh8@gmail.com', 'http://localhost/wordpress', '::1', '2026-09-09 02:10:55', '2026-09-09 02:10:55', 'hihihih', 0, '1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', 'comment', 0, 1),
(3, 22, 'admin', 'tranthitrucanh8@gmail.com', 'http://localhost/wordpress', '::1', '2026-09-09 02:14:24', '2026-09-09 02:14:24', 'quá xịn', 0, '1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', 'comment', 0, 1),
(4, 17, 'Trúc Anh', 'user1@gmail.com', '', '127.0.0.1', '2026-09-11 10:19:57', '2026-09-11 03:19:57', 'kkkk', 0, '0', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Safari/537.36', 'comment', 0, 7);
